export const scripts: string[] = ["\n    function calculateEstimate() {\n      const bikeType = document.getElementById('bikeType').value;\n      const regYear = parseInt(document.getElementById('regYear').value, 10);\n      const policyStatus = document.getElementById('policyStatus').value;\n\n      let baseTP = 538;\n      let baseComp = 950;\n      let ncbText = \"Includes estimated 35% No Claim Bonus\";\n\n      // CC Tariff adjustments\n      if (bikeType === 'scooter') {\n        baseTP = 538;\n        baseComp = 890;\n      } else if (bikeType === 'commuter') {\n        baseTP = 714;\n        baseComp = 1050;\n      } else if (bikeType === 'sports') {\n        baseTP = 1366;\n        baseComp = 1850;\n      } else if (bikeType === 'superbike') {\n        baseTP = 2800;\n        baseComp = 3800;\n      }\n\n      // Age calculation\n      const age = 2025 - regYear;\n      if (age <= 1) {\n        baseComp = Math.round(baseComp * 1.35); // Zero Dep higher on new bikes\n      } else if (age >= 4) {\n        baseComp = Math.round(baseComp * 0.85); // Lower IDV\n      }\n\n      // NCB Impact\n      if (policyStatus === 'lapsed_over_90') {\n        ncbText = \"\u26a0\ufe0f NCB reset to 0% (Policy expired > 90 days)\";\n        baseComp = Math.round(baseComp * 1.35);\n      } else if (policyStatus === 'lapsed_under_90') {\n        ncbText = \"Preserved 20%-50% NCB bonus applies\";\n      }\n\n      document.getElementById('tpPremium').textContent = '\u20b9' + baseTP.toLocaleString('en-IN') + ' / yr';\n      document.getElementById('compPremium').textContent = '\u20b9' + baseComp.toLocaleString('en-IN') + '*';\n      document.getElementById('ncbTag').textContent = ncbText;\n    }\n\n    function submitWhatsAppQuote() {\n      const bike = document.getElementById('bikeType').options[document.getElementById('bikeType').selectedIndex].text;\n      const year = document.getElementById('regYear').value;\n      const status = document.getElementById('policyStatus').options[document.getElementById('policyStatus').selectedIndex].text;\n      const regNo = document.getElementById('bikeRegNumber').value || 'New/Not Provided';\n\n      const text = encodeURIComponent(\n        \"Hi Deeksha Insurance Desk, I need a two-wheeler quote for:\\n\" +\n        \"\u2022 Bike Category: \" + bike + \"\\n\" +\n        \"\u2022 Reg Year: \" + year + \"\\n\" +\n        \"\u2022 Status: \" + status + \"\\n\" +\n        \"\u2022 Reg No: \" + regNo + \"\\n\" +\n        \"Please calculate the lowest ICICI Lombard premium.\"\n      );\n      window.open('https://wa.me/916374423164?text=' + text, '_blank');\n    }\n\n    function toggleFaq(id) {\n      const content = document.getElementById('content-' + id);\n      const icon = document.getElementById('icon-' + id);\n      if (content.classList.contains('hidden')) {\n        content.classList.remove('hidden');\n        icon.style.transform = 'rotate(180deg)';\n      } else {\n        content.classList.add('hidden');\n        icon.style.transform = 'rotate(0deg)';\n      }\n    }\n  "];
